INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_kfk_111'), 1, 'Kafka keeps an order per partition, not per topic. Ask which partition each event of order o-1842 went to when the events had no key.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_kfk_111'), 2, 'The key decides the partition. How many distinct keys does a restaurant chain with hundreds of orders produce, and how many partitions can those keys land in?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_kfk_111'), 3, 'The default partitioner takes the key''s hash modulo the partition count. What happens to that result when the count changes from 12 to 24?');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_kfk_111');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_kfk_111'), 'The notifications service sent "Your courier is here" before "A courier accepted your order". The producer sent every event without a key:

```text
$ kafka-console-consumer --bootstrap-server kafka:9092 --topic orders.v1 --from-beginning \
    --property print.partition=true --property print.offset=true | grep o-1842
Partition:3  Offset:5120  {"type":"OrderPlaced","orderId":"o-1842"}
Partition:0  Offset:4987  {"type":"OrderAccepted","orderId":"o-1842"}
Partition:5  Offset:5302  {"type":"CourierAssigned","orderId":"o-1842"}
Partition:1  Offset:5011  {"type":"OrderDelivered","orderId":"o-1842"}
```

Statement: "Kafka delivers a topic''s messages in the order they were produced, so the notifications consumer must be reordering them; the fix belongs in the consumer."', 'single_choice'::question_type, 'False. Kafka orders messages within one partition only. Without a key the producer spread o-1842''s four events over partitions 3, 0, 5 and 1, and a consumer group reads partitions independently, so OrderDelivered on partition 1 can be processed before CourierAssigned on partition 5. Keying every event by its order id puts all of an order''s events in one partition, in produce order. The misconception is that a topic is one ordered queue.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_kfk_111') AND order_index = 1)
    RETURNING id
)
