    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_kfk_111'), 'After keying events by `restaurantId`, the lunch rush looked like this (one consumer per partition):

```text
$ kafka-consumer-groups --bootstrap-server kafka:9092 --describe --group courier-matcher
GROUP            TOPIC      PARTITION  CURRENT-OFFSET  LOG-END-OFFSET  LAG
courier-matcher  orders.v1  0          88412           88420           8
courier-matcher  orders.v1  4          301877          320102          18225
courier-matcher  orders.v1  7          91033           91040           7
... (9 more partitions with a lag under 10)
```

Statement: "Every order of the big chain shares one key, so they all hash to partition 4 and one consumer does most of the work; keying by order id spreads the chain''s orders and still keeps each order''s events in order."', 'single_choice'::question_type, 'True. One key always maps to the same partition, so a key with most of the traffic makes a hot partition, and adding consumers does not help: a partition is read by one consumer of the group. Order ids are many and roughly uniform, so they spread over all partitions, and each order''s events still share one key. The misconception is that keying by a coarse entity (restaurant, city) is safer; it is only needed when events of different orders must be ordered relative to each other.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_kfk_111') AND order_index = 2)
    RETURNING id
)
