INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_kfk_112', (SELECT id FROM catalog.course WHERE public_id = 'kafka-event-streaming'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'kafka-event-streaming') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-kfk-1-1' AND is_deleted = false LIMIT 1), 'order-events-producer', 'Key the order events', 'The api''s first producer sent order events without a key, and OrderDelivered sometimes reached consumers before CourierAssigned; keying by restaurant then made one partition carry the lunch rush of a big chain. The editor holds `main.ts`: the topic spec `ORDERS_TOPIC` and `toMessage(event)` with their key blocks missing, each marked by a `// [ ]` line; some pieces are wrong on purpose. Fill every line so that: `orders.v1` has 12 partitions, replication factor 3 and `min.insync.replicas` 2; every event of one order lands in one partition, in the order it was produced; the chain''s orders do not pile onto one partition; and each record carries the headers `event-type` and `schema-version` ("1"). Run produces a lunch rush into an in-memory broker that uses Kafka''s default partitioner (murmur2 of the key).', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
