INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_112'), 1, 'Ask what must stay in order: the events of one order, or the events of one restaurant? The key decides the partition, and only a partition is ordered.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_112'), 2, 'Look at the key returned by `toMessage`, the `headers` object of the message, and `numPartitions`, `replicationFactor` and `configEntries` of the topic spec.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_112'), 3, 'Courier GPS pings, where each courier''s pings must stay in order and couriers are many: `const COURIERS_TOPIC = { topic: "couriers.v1", numPartitions: 6, replicationFactor: 3, configEntries: [{ name: "min.insync.replicas", value: "2" }] }` and `const key = ping.courierId;` with `headers = { "event-type": "CourierPing", "schema-version": "2" }`.');
