UPDATE course.lesson SET title = 'Idempotent producers and acks', order_index = 2, module_id = (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'kafka-event-streaming') AND order_index = 1 AND is_deleted = false LIMIT 1), updated_at = now() WHERE id = (SELECT id FROM course.lesson WHERE content_source = 'lesson-kfk-1-2' AND is_deleted = false LIMIT 1);
