WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-kfk-1-2' AND is_deleted = false);

-- challenge chal_quiz_kfk_121 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_kfk_121', (SELECT id FROM catalog.course WHERE public_id = 'kafka-event-streaming'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'kafka-event-streaming') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-kfk-1-2' AND is_deleted = false LIMIT 1), 'producer-acks-quiz', 'Read the lost and the doubled events', 'Three statements about the two producer incidents Rice Rocket had with its first producer settings. Decide whether each one is true.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_kfk_121');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_kfk_121'), 1, 'With acks=1 the leader answers as soon as it has the record. Where else is the record at that moment, and what does a broker do with records the new leader never had when it rejoins as a follower?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_kfk_121'), 2, 'A producer that does not get an acknowledgement in time cannot know whether the write happened. What does it do when retries are on, and what lets a broker recognise a resend?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_kfk_121'), 3, 'Read min.insync.replicas as a rule for writes with acks=all: how many replicas must be in sync, and what kind of error does the producer get when they are not?');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_kfk_121');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_kfk_121'), 'The producer used `acks=1`. The leader of partition 7 went down, and one OrderPlaced is missing:

```text
[api] produced OrderPlaced o-2977 -> orders.v1 [7] offset 48120 (acks=1)
[broker-2] partition orders.v1-7: leader shutting down
[broker-3] partition orders.v1-7: elected leader, log end offset 48120
[broker-2] partition orders.v1-7: became follower, truncating log to offset 48120
$ kafka-console-consumer ... --partition 7 --offset 48119 --max-messages 2
{"type":"OrderAccepted","orderId":"o-2971"}
{"type":"OrderPlaced","orderId":"o-2980"}
```

Statement: "With acks=1 the event reached the leader''s disk, so when broker-2 came back it restored offset 48120 and nothing was lost."', 'single_choice'::question_type, 'False. acks=1 means only the leader had the record when the producer was told it succeeded. broker-3 became leader without it, and broker-2, rejoining as a follower, truncated its log to match the new leader, discarding o-2977. The offset was then reused by o-2980. With acks=all the leader answers only after every in-sync replica has the record, so a leader change cannot drop an acknowledged event. The misconception is that "on the leader''s disk" means durable.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_kfk_121') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_kfk_121'), 'After turning on retries (idempotence off), courier-matcher offered order o-3050 to two couriers:

```text
[api] OrderPlaced o-3050 (eventId evt-o-3050-1): request timed out after 30000 ms, retrying
[api] OrderPlaced o-3050 (eventId evt-o-3050-1): delivered to orders.v1 [2] offset 77310
$ kafka-console-consumer ... --partition 2 --offset 77309 --max-messages 2
{"eventId":"evt-o-3050-1","type":"OrderPlaced","orderId":"o-3050"}
{"eventId":"evt-o-3050-1","type":"OrderPlaced","orderId":"o-3050"}
```

Statement: "The duplicate comes from courier-matcher reading offset 77309 twice; the producer settings play no part in it."', 'single_choice'::question_type, 'False. The log itself holds the event twice, at offsets 77309 and 77310: the first request was written but its acknowledgement was lost, so the producer sent it again. With `enable.idempotence` the producer gets a producer id and numbers each record per partition; the broker sees the same sequence number again and acknowledges without writing a second copy. Consumers should still be idempotent (they can see an event again after a rebalance), but this duplicate was made by the producer.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_kfk_121') AND order_index = 2)
    RETURNING id
)
