WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_kfk_131'), 'Every scale event of the HPA stalls the whole group for a few seconds. The client log of a pod that kept its partitions:

```text
[courier-matcher-7f9c-0a1b] rebalance: revoking all assigned partitions: orders.v1 [0, 1]
[courier-matcher-7f9c-0a1b] rebalance: assigned partitions: orders.v1 [0, 1]
```

```ts
// consumer config
{ "group.id": "courier-matcher", "partition.assignment.strategy": "range" }
```

Statement: "With the eager protocol every member gives up all its partitions at the start of each rebalance, even the ones it gets back, so the whole group stops; cooperative-sticky assignment moves only the partitions that change owner."', 'single_choice'::question_type, 'True. Under the eager protocol (the range and round-robin assignors) a rebalance starts with every member revoking everything, then a new assignment is handed out: nobody reads until the rebalance completes, which is the stall seen on each HPA event. The cooperative-sticky assignor rebalances incrementally: members keep the partitions they still own and only the moved ones are revoked and reassigned. Kafka 4 also brings a broker-driven consumer group protocol (KIP-848) that works incrementally; check that your client supports it before switching.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_kfk_131') AND order_index = 2)
    RETURNING id
)
