VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_132'), 1, 'Follow one record across a rebalance: who handled it, what the old owner committed, and where the new owner starts. A duplicate means the commit was too low; a lost record means it was too high.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_132'), 2, 'There are two offsets per partition in the worker: `position` (what has been fetched) and `done` (what has been handled). Which one is safe to commit, and when does `onRevoke` need to stop the worker from reading a partition?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_132'), 3, 'A billing worker on topic invoices.v1 keeps `const paid = new Map<number, number>()`; in onAssign it sets `paid.set(p, broker.committedOffset("billing", "invoices.v1", p) ?? 0)`, after each charged invoice `paid.set(p, invoice.offset + 1)`, and in onRevoke it commits `paid.get(p)` for each revoked partition before deleting it from its maps.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_132'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"resume-from-committed","label":"Where each new partition starts reading","code":"for (const p of partitions) {\n    const start = broker.committedOffset(GROUP, TOPIC, p) ?? 0;\n    position.set(p, start);\n    done.set(p, start);\n}"},{"id":"handle-batch","label":"Handle the batch in order, stop if a rebalance starts","code":"for (const record of batch) {\n    if (!handle(record)) return;\n    done.set(p, record.offset + 1);\n}"},{"id":"commit-on-revoke","label":"Save the progress of the partitions being taken away","code":"for (const p of partitions) {\n    const next = done.get(p);\n    if (next !== undefined) broker.commit(GROUP, TOPIC, p, next);\n}"},{"id":"forget-revoked","label":"Stop reading the partitions given away","code":"for (const p of partitions) {\n    position.delete(p);\n    done.delete(p);\n}"},{"id":"commit-fetched-offset","label":"Save the progress of the partitions being taken away","code":"for (const p of partitions) {\n    const next = position.get(p);\n    if (next !== undefined) broker.commit(GROUP, TOPIC, p, next);\n}","distractor":true},{"id":"commit-nothing","label":"Save the progress of the partitions being taken away","code":"for (const p of partitions) done.delete(p);","distractor":true},{"id":"resume-from-zero","label":"Where each new partition starts reading","code":"for (const p of partitions) {\n    position.set(p, 0);\n    done.set(p, 0);\n}","distractor":true}]'::jsonb)
