       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_132'), 'A rebalance interrupts a batch: the unhandled orders go to the next owner', '{"records":24,"steps":[{"join":"pod-a"},{"poll":"pod-a","max":4,"stopAfter":3},{"join":"pod-b"},{"drain":true}]}', '{"assignment":{"pod-a":[0,1,2],"pod-b":[3,4,5]},"handled":24,"duplicates":[],"lost":[],"committed":{"0":4,"1":3,"2":3,"3":6,"4":4,"5":4}}', 6, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_132'), 'Nine pods for six partitions: three get nothing and every order is handled once', '{"records":30,"steps":[{"join":"pod-a"},{"join":"pod-b"},{"join":"pod-c"},{"join":"pod-d"},{"join":"pod-e"},{"join":"pod-f"},{"join":"pod-g"},{"join":"pod-h"},{"join":"pod-i"},{"drain":true}]}', '{"assignment":{"pod-a":[0],"pod-b":[1],"pod-c":[2],"pod-d":[3],"pod-e":[4],"pod-f":[5],"pod-g":[],"pod-h":[],"pod-i":[]},"handled":30,"duplicates":[],"lost":[],"committed":{"0":5,"1":4,"2":4,"3":6,"4":5,"5":6}}', 4, false, true, 4),
