       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_132'), 'Scale from three pods down to one: progress carries over every rebalance', '{"records":36,"steps":[{"join":"pod-a"},{"join":"pod-b"},{"join":"pod-c"},{"poll":"pod-a","max":2},{"poll":"pod-b","max":3,"stopAfter":4},{"poll":"pod-c","max":1},{"leave":"pod-c"},{"poll":"pod-a","max":2},{"leave":"pod-b"},{"drain":true}]}', '{"assignment":{"pod-a":[0,1,2,3,4,5]},"handled":36,"duplicates":[],"lost":[],"committed":{"0":5,"1":7,"2":5,"3":6,"4":7,"5":6}}', 5, false, true, 6);
