-- challenge chal_coding_kfk_142 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_kfk_142', (SELECT id FROM catalog.course WHERE public_id = 'kafka-event-streaming'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'kafka-event-streaming') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-kfk-2-2' AND is_deleted = false LIMIT 1), 'notification-consumer-commits', 'Fix the notification consumer', 'Rice Rocket''s notifications consumer pushes "Your order ... is on the way" when an order is picked up. With auto-commit, an OOM-killed pod lost 300 pushes; the first fix then re-sent pushes after every crash, and one version never caught up with the end of the topic. The editor holds `runConsumer` with its key blocks missing, each marked by a `// [ ]` line; the pieces include the buggy versions. Fill every line so that: nothing is committed before the batch''s pushes went out; each partition''s commit is the offset after its last handled record; and a push that runs again after a kill is not delivered twice (the push gateway drops a send whose `idempotencyKey` it has already accepted; the pod''s memory does not survive a kill). Run feeds order events to `orders.v1`, kills the pod right after a push or during a commit, restarts it from the committed offsets and counts the pushes customers received.', 'open', 'hard'::difficulty_question, 'fix_bug', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_142');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_142'), 1, 'Write down, for one kill, three things: which pushes were already delivered, which offsets were committed, and what survives the restart. A lost push means a commit ran ahead of the work; a duplicate means the retry could not tell it was a retry.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_142'), 2, 'Look at where `consumer.commit` can run relative to `push.send`, at the value stored per partition (the committed offset is the next record to read), and at what the dedupe relies on: a Set in the pod, or a key the gateway keeps.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_142'), 3, 'An invoice consumer that charges cards does: fetch a batch; for each record `payments.charge({ amount, idempotencyKey: invoice.invoiceId })`, then `done.set(record.partition, record.offset + 1)`; after the loop `for (const [p, o] of done) consumer.commit(p, o)`. A crash before the commit re-runs the charges, and the payment provider drops them by key.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_142'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"fetch-batch","label":"Fetch the next batch","code":"const batch = consumer.poll(50);"},{"id":"send-push","label":"Push \"on the way\" so a re-run cannot send it twice","code":"if (event.status === \"picked_up\") {\n    push.send({ userId: event.customerId, text: `Your order ${event.orderId} is on the way`, idempotencyKey: event.eventId });\n}"},{"id":"mark-done","label":"Remember how far each partition got","code":"next.set(record.partition, record.offset + 1);"},{"id":"commit-batch","label":"Commit once the batch''s pushes went out","code":"for (const [partition, offset] of next) consumer.commit(partition, offset);"},{"id":"dedupe-in-memory","label":"Push \"on the way\" so a re-run cannot send it twice","code":"if (event.status === \"picked_up\" && !seen.has(event.eventId)) {\n    seen.add(event.eventId);\n    push.send({ userId: event.customerId, text: `Your order ${event.orderId} is on the way` });\n}","distractor":true},{"id":"fetch-and-commit","label":"Fetch the next batch","code":"const batch = consumer.poll(50);\nfor (const record of batch) consumer.commit(record.partition, record.offset + 1);","distractor":true},{"id":"mark-last-offset","label":"Remember how far each partition got","code":"next.set(record.partition, record.offset);","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
