VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_142'), 'No kill: every picked-up order gets one push and the commits reach the end', '{"orders":12}', '{"pushes":12,"duplicates":[],"missing":[],"committedAtEnd":true,"restarts":0}', 6, true, false, 1),
