-- challenge chal_coding_kfk_152 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_kfk_152', (SELECT id FROM catalog.course WHERE public_id = 'kafka-event-streaming'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'kafka-event-streaming') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-kfk-2-3' AND is_deleted = false LIMIT 1), 'retry-and-dead-letter-routing', 'Route failed orders through retry topics to a dead-letter topic', 'The courier-matcher''s first version let a matching error escape `eachMessage`: one OrderPlaced without an address was retried forever and held up every order behind it on partition 5. The editor holds `src/failures.ts`: `onRecord`, called for every record of `orders.v1` and of the retry topics, and `routeFailure`, which picks where a failed record goes next. Their key blocks are missing, each marked by a `// [ ]` line; some pieces are wrong on purpose. Fill every line so that: a failure never stops the partition (the record is published onward and the consumer moves on); validation and schema errors go to `orders.v1.dlt` at once; timeout and unavailable errors go to `orders.v1.retry.30s` after the 1st failure, `orders.v1.retry.5m` after the 2nd and the dead-letter topic after the 3rd; every forwarded record carries `x-attempts`, `x-error` and, kept from its first failure, `x-original-topic`, `x-original-partition`, `x-original-offset` and `x-first-failed-at`. The runner replays a lunch rush second by second against an in-memory broker, with a poison order and an outage of the maps API.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_152');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_152'), 1, 'Follow one record through three failures: which topic does it land in each time, what do its headers say, and does the consumer move to the next offset after each failure or stay where it is?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_152'), 2, 'Look at what the catch block does with the error, how `x-attempts` is read from the incoming headers (a record from a retry topic already has some), which headers must keep their first value (`??`), and which failure kinds skip the retry topics.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_152'), 3, 'A payment webhook consumer with retry topics `pay.retry.1m` and `pay.retry.10m`: `const tries = Number(h["x-tries"] ?? "0") + 1; if (err.kind === "signature") return { topic: "pay.dlt", headers }; return { topic: RETRIES[tries - 1] ?? "pay.dlt", headers };` and in the handler `try { pay(record) } catch (e) { const next = route(record, e); publish(next.topic, { ...record, headers: next.headers }); }`.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_152'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"handle-or-route","label":"Run the handler; a failure sends the record on","code":"try {\n    deps.handle(record);\n} catch (error) {\n    const next = routeFailure(record, error as Failure, nowMs);\n    deps.publish(next.topic, { key: record.key, value: record.value, headers: next.headers });\n}"},{"id":"count-attempts","label":"How many times the record has failed, this time included","code":"const attempts = Number(previous[\"x-attempts\"] ?? \"0\") + 1;"},{"id":"origin-headers","label":"Where and when the record failed the first time","code":"const origin: Headers = {\n    \"x-original-topic\": previous[\"x-original-topic\"] ?? record.topic,\n    \"x-original-partition\": previous[\"x-original-partition\"] ?? String(record.partition),\n    \"x-original-offset\": previous[\"x-original-offset\"] ?? String(record.offset),\n    \"x-first-failed-at\": previous[\"x-first-failed-at\"] ?? String(nowMs),\n};"},{"id":"bad-data-to-dlt","label":"Failures that no retry can fix","code":"if (failure.kind === \"validation\" || failure.kind === \"schema\") return { topic: DEAD_LETTER_TOPIC, headers };"},{"id":"next-retry-topic","label":"Retryable failures: the next retry topic, then the DLT","code":"return { topic: RETRY_TOPICS[attempts - 1] ?? DEAD_LETTER_TOPIC, headers };"},{"id":"attempts-reset","label":"How many times the record has failed, this time included","code":"const attempts = 1;","distractor":true},{"id":"dlt-everything","label":"Failures that no retry can fix","code":"return { topic: DEAD_LETTER_TOPIC, headers };","distractor":true},{"id":"handle-propagates","label":"Run the handler; a failure sends the record on","code":"deps.handle(record);","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, snippets = EXCLUDED.snippets, updated_at = now();
