INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_172'), 1, 'For each mode write down who reads and who wrote the data: in BACKWARD the consumers move to the new schema first, so the new schema reads events the old schema wrote.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_172'), 2, 'Look at three places: the list of versions the candidate is compared with, the two `canRead(reader, writer)` calls and their argument order, and the required-field loop (does a `default` change anything in JSON Schema validation?).'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_172'), 3, 'The same shape for an HTTP API: "can a v2 server accept a request from a v1 client?" is `canAccept(server = v2, client = v1)`, and every header the v2 server requires must be one the v1 client always sends: `for (const h of server.required) if (!client.alwaysSends.includes(h)) problems.push(...)`. A v2 server that relies on a default value it never applies still rejects the request.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_172'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"pick-versions","label":"Which earlier versions the candidate is checked against","code":"const against = mode.endsWith(\"_TRANSITIVE\") ? versions : versions.slice(-1);"},{"id":"directions","label":"Who reads whose data in this mode","code":"if (mode.startsWith(\"BACKWARD\") || mode.startsWith(\"FULL\")) problems.push(...canRead(next, old));\nif (mode.startsWith(\"FORWARD\") || mode.startsWith(\"FULL\")) problems.push(...canRead(old, next));"},{"id":"required-fields","label":"Fields the reader cannot do without","code":"for (const field of reader.schema.required ?? []) {\n    if (!guaranteed.has(field)) problems.push(`${where}: \"${field}\" is required but may be missing`);\n}"},{"id":"type-changes","label":"Fields both sides declare","code":"for (const [field, spec] of Object.entries(reader.schema.properties)) {\n    const written = writer.schema.properties[field];\n    if (written && written.type !== spec.type) problems.push(`${where}: \"${field}\" changed from ${written.type} to ${spec.type}`);\n}"},{"id":"directions-swapped","label":"Who reads whose data in this mode","code":"if (mode.startsWith(\"BACKWARD\") || mode.startsWith(\"FULL\")) problems.push(...canRead(old, next));\nif (mode.startsWith(\"FORWARD\") || mode.startsWith(\"FULL\")) problems.push(...canRead(next, old));","distractor":true},{"id":"latest-only","label":"Which earlier versions the candidate is checked against","code":"const against = versions.slice(-1);","distractor":true},{"id":"required-default-is-safe","label":"Fields the reader cannot do without","code":"for (const field of reader.schema.required ?? []) {\n    const hasDefault = reader.schema.properties[field]?.default !== undefined;\n    if (!guaranteed.has(field) && !hasDefault) problems.push(`${where}: \"${field}\" is required but may be missing`);\n}","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, snippets = EXCLUDED.snippets, updated_at = now();
