       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_172'), 'The incident under FORWARD: old consumers still require deliveryAddress', '{"history":[{"properties":{"orderId":{"type":"string"},"restaurantId":{"type":"string"},"deliveryAddress":{"type":"string"},"total":{"type":"integer"},"tip":{"type":"integer","default":0}},"required":["orderId","restaurantId","deliveryAddress","total"]}],"candidate":{"properties":{"orderId":{"type":"string"},"restaurantId":{"type":"string"},"address":{"type":"string"},"total":{"type":"integer"},"tip":{"type":"integer","default":0}},"required":["orderId","restaurantId","address","total","tip"]},"mode":"FORWARD"}', '{"compatible":false,"problems":["v1 reading new: \"deliveryAddress\" is required but may be missing"]}', 5, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_172'), 'FULL reports an optional field that changes type in both directions', '{"history":[{"properties":{"orderId":{"type":"string"},"restaurantId":{"type":"string"},"deliveryAddress":{"type":"string"},"total":{"type":"integer"},"tip":{"type":"integer","default":0}},"required":["orderId","restaurantId","deliveryAddress","total"]}],"candidate":{"properties":{"orderId":{"type":"string"},"restaurantId":{"type":"string"},"deliveryAddress":{"type":"string"},"total":{"type":"integer"},"tip":{"type":"string","default":"0"}},"required":["orderId","restaurantId","deliveryAddress","total"]},"mode":"FULL"}', '{"compatible":false,"problems":["new reading v1: \"tip\" changed from integer to string","v1 reading new: \"tip\" changed from string to integer"]}', 5, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_172'), 'BACKWARD_TRANSITIVE compares with v1 too; plain BACKWARD only sees v2', '{"history":[{"properties":{"orderId":{"type":"string"},"restaurantId":{"type":"string"},"deliveryAddress":{"type":"string"},"total":{"type":"integer"},"tip":{"type":"integer","default":0},"note":{"type":"integer"}},"required":["orderId","restaurantId","deliveryAddress","total"]},{"properties":{"orderId":{"type":"string"},"restaurantId":{"type":"string"},"deliveryAddress":{"type":"string"},"total":{"type":"integer"},"tip":{"type":"integer","default":0}},"required":["orderId","restaurantId","deliveryAddress","total"]}],"candidate":{"properties":{"orderId":{"type":"string"},"restaurantId":{"type":"string"},"deliveryAddress":{"type":"string"},"total":{"type":"integer"},"tip":{"type":"integer","default":0},"note":{"type":"string","default":""}},"required":["orderId","restaurantId","deliveryAddress","total"]},"mode":"BACKWARD_TRANSITIVE"}', '{"compatible":false,"problems":["new reading v1: \"note\" changed from integer to string"]}', 5, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_kfk_172'), 'FULL_TRANSITIVE accepts a safe change checked against every earlier version', '{"history":[{"properties":{"orderId":{"type":"string"},"restaurantId":{"type":"string"},"deliveryAddress":{"type":"string"},"total":{"type":"integer"},"tip":{"type":"integer","default":0}},"required":["orderId","restaurantId","deliveryAddress","total"]},{"properties":{"orderId":{"type":"string"},"restaurantId":{"type":"string"},"deliveryAddress":{"type":"string"},"total":{"type":"integer"},"tip":{"type":"integer","default":0},"couponCode":{"type":"string","default":""}},"required":["orderId","restaurantId","deliveryAddress","total"]}],"candidate":{"properties":{"orderId":{"type":"string"},"restaurantId":{"type":"string"},"deliveryAddress":{"type":"string"},"total":{"type":"integer"},"tip":{"type":"integer","default":0},"couponCode":{"type":"string","default":""},"courierNote":{"type":"string","default":""}},"required":["orderId","restaurantId","deliveryAddress","total"]},"mode":"FULL_TRANSITIVE"}', '{"compatible":true,"problems":[]}', 5, false, true, 6);
